<script lang="ts">import type {DayLoad} from '../generated/DayLoad';let {days}:{days:DayLoad[]}=$props();let max=$derived(Math.max(1,...days.map(d=>d.load)));</script><div class="wk">{#each days as d,i}<div>{#if d.load}<b>{Math.round(d.load)}</b>{/if}<i style:height={Math.max(4,d.load/max*80)+'px'} style:background={d.load?(i===days.length-1?'#E4E8F0':'rgba(228,232,240,.30)'):'rgba(255,255,255,.08)'}></i><span>{new Date(d.date+'T12:00:00').toLocaleDateString('en',{weekday:'narrow'})}</span></div>{/each}</div><style>.wk{display:flex;justify-content:space-between;align-items:flex-end;height:110px;gap:8px}.wk div{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;gap:6px}.wk i{display:block;width:100%;border-radius:8px 8px 4px 4px;min-height:4px}.wk b{font:600 11px Outfit;color:var(--text2)}.wk span{font:600 11px Inter;color:var(--text3)}</style>